#include "xxhash.h"
#include <string.h>

#define PRIME32_1 2654435761U
#define PRIME32_2 2246822519U
#define PRIME32_3 3266489917U
#define PRIME32_4  668265263U
#define PRIME32_5  374761393U

static inline uint32_t rotl32(uint32_t x, int r) {
    return (x << r) | (x >> (32 - r));
}

static inline uint32_t read_le32(const uint8_t *p) {
    return ((uint32_t)p[0]) | ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static inline uint32_t round32(uint32_t acc, uint32_t input) {
    acc += input * PRIME32_2;
    acc = rotl32(acc, 13);
    acc *= PRIME32_1;
    return acc;
}

void XXH32_reset(XXH32_state_t *state, uint32_t seed) {
    state->seed = seed;
    state->v[0] = seed + PRIME32_1 + PRIME32_2;
    state->v[1] = seed + PRIME32_2;
    state->v[2] = seed + 0;
    state->v[3] = seed - PRIME32_1;
    state->total_len = 0;
    state->buf_len = 0;
}

void XXH32_update(XXH32_state_t *state, const void *input, size_t len) {
    const uint8_t *p = (const uint8_t *)input;
    const uint8_t *end = p + len;
    state->total_len += len;

    if (state->buf_len + len < 16) {
        memcpy(state->buf + state->buf_len, input, len);
        state->buf_len += (uint32_t)len;
        return;
    }

    if (state->buf_len > 0) {
        size_t need = 16 - state->buf_len;
        memcpy(state->buf + state->buf_len, p, need);
        state->v[0] = round32(state->v[0], read_le32(state->buf + 0));
        state->v[1] = round32(state->v[1], read_le32(state->buf + 4));
        state->v[2] = round32(state->v[2], read_le32(state->buf + 8));
        state->v[3] = round32(state->v[3], read_le32(state->buf + 12));
        p += need;
        state->buf_len = 0;
    }

    while (p + 16 <= end) {
        state->v[0] = round32(state->v[0], read_le32(p + 0));
        state->v[1] = round32(state->v[1], read_le32(p + 4));
        state->v[2] = round32(state->v[2], read_le32(p + 8));
        state->v[3] = round32(state->v[3], read_le32(p + 12));
        p += 16;
    }

    if (p < end) {
        state->buf_len = (uint32_t)(end - p);
        memcpy(state->buf, p, state->buf_len);
    }
}

uint32_t XXH32_digest(const XXH32_state_t *state) {
    uint32_t h32;
    if (state->total_len >= 16) {
        h32 = rotl32(state->v[0], 1) + rotl32(state->v[1], 7) +
              rotl32(state->v[2], 12) + rotl32(state->v[3], 18);
    } else {
        h32 = state->seed + PRIME32_5;
    }

    h32 += (uint32_t)state->total_len;

    const uint8_t *p = state->buf;
    uint32_t remaining = state->buf_len;
    while (remaining >= 4) {
        h32 += read_le32(p) * PRIME32_3;
        h32 = rotl32(h32, 17) * PRIME32_4;
        p += 4;
        remaining -= 4;
    }
    while (remaining > 0) {
        h32 += (*p) * PRIME32_5;
        h32 = rotl32(h32, 11) * PRIME32_1;
        p++;
        remaining--;
    }

    h32 ^= h32 >> 15;
    h32 *= PRIME32_2;
    h32 ^= h32 >> 13;
    h32 *= PRIME32_3;
    h32 ^= h32 >> 16;
    return h32;
}

uint32_t XXH32(const void *input, size_t len, uint32_t seed) {
    XXH32_state_t state;
    XXH32_reset(&state, seed);
    XXH32_update(&state, input, len);
    return XXH32_digest(&state);
}
EOF

