#include "lz4.h"
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

#define LZ4_MINMATCH 4
#define LZ4_MFLIMIT 12      /* margin at end: no match starts in last MFLIMIT bytes */
#define LZ4_LASTLITERALS 5  /* last 5 bytes are literals */
#define LZ4_SKIPSTRENGTH 6

#define ML_BITS 4
#define ML_MASK ((1U<<ML_BITS)-1)
#define RUN_BITS (8-ML_BITS)
#define RUN_MASK ((1U<<RUN_BITS)-1)

#define LZ4_HASHLOG 14
#define LZ4_HASH_SIZE (1U << LZ4_HASHLOG)

int LZ4_compressBound(int isize) {
    if (isize < 0 || isize > 0x7E000000) return 0;
    return isize + (isize / 255) + 16;
}

static inline uint32_t read_u32(const void *p) {
    uint32_t v;
    memcpy(&v, p, 4);
    return v;
}

static inline uint16_t read_u16(const void *p) {
    uint16_t v;
    memcpy(&v, p, 2);
    return v;
}

static inline void write_u16(void *p, uint16_t v) {
    memcpy(p, &v, 2);
}

static inline uint32_t hash_pos(uint32_t seq) {
    return (seq * 2654435761U) >> (32 - LZ4_HASHLOG);
}

int LZ4_compress_default(const char *src_c, char *dst_c, int src_size, int dst_capacity) {
