#include "lz4frame.h"
#include "lz4.h"
#include "xxhash.h"
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

size_t LZ4F_block_size(int id) {
    switch (id) {
        case 4: return 64 * 1024;
        case 5: return 256 * 1024;
        case 6: return 1024 * 1024;
        case 7: return 4 * 1024 * 1024;
        default: return 64 * 1024;
    }
}

static int block_size_id_for(size_t sz) {
    if (sz <= 64 * 1024) return 4;
    if (sz <= 256 * 1024) return 5;
    if (sz <= 1024 * 1024) return 6;
    return 7;
}

static void write_le32(uint8_t *p, uint32_t v) {
    p[0] = v & 0xff;
    p[1] = (v >> 8) & 0xff;
    p[2] = (v >> 16) & 0xff;
    p[3] = (v >> 24) & 0xff;
}

static uint32_t read_le32(const uint8_t *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static void write_le64(uint8_t *p, uint64_t v) {
    for (int i = 0; i < 8; i++) p[i] = (v >> (i*8)) & 0xff;
}

int LZ4F_compress_file(FILE *in, FILE *out,
                       const LZ4F_prefs_t *prefs,
                       uint64_t content_size,
                       uint64_t *bytes_read,
                       uint64_t *bytes_written,
                       const uint8_t *dict, size_t dict_size) {
    (void)dict; (void)dict_size;
    int block_size_id = prefs->block_size_id;
    if (block_size_id < 4) block_size_id = 4;
    if (block_size_id > 7) block_size_id = 7;

    /* First read content to determine size; if we know we're small, downgrade block size */
    /* But we need to stream, so only downgrade if content_size is known */
    if (content_size > 0 && content_size < (1ULL << 31)) {
        int min_id = block_size_id_for((size_t)content_size);
        if (min_id < block_size_id) block_size_id = min_id;
    }

    size_t block_size = LZ4F_block_size(block_size_id);

    uint8_t header[19];
    size_t hpos = 0;
    /* Magic */
    write_le32(header + hpos, LZ4F_MAGIC); hpos += 4;
    /* FLG: bit7-6 version (01), bit5 indep, bit4 BCksum, bit3 ContSize, bit2 CContSum, bit0 DictID */
    uint8_t flg = 0x40;
    if (prefs->block_mode == 1) flg |= 0x20;
    if (prefs->block_checksum) flg |= 0x10;
    if (prefs->content_size) flg |= 0x08;
    if (prefs->content_checksum) flg |= 0x04;
    header[hpos++] = flg;
    /* BD: bits 6-4 block size id */
    uint8_t bd = (uint8_t)(block_size_id << 4);
    header[hpos++] = bd;
    /* Optional content size */
    if (prefs->content_size) {
        write_le64(header + hpos, content_size);
        hpos += 8;
    }
    /* HC: byte 2 (third byte) of xxhash32 of the bytes between magic and HC */
    uint32_t hc = XXH32(header + 4, hpos - 4, 0);
    header[hpos++] = (uint8_t)((hc >> 8) & 0xff);

    if (fwrite(header, 1, hpos, out) != hpos) return -1;
    *bytes_written += hpos;

    uint8_t *input_buf = (uint8_t *)malloc(block_size);
    int compressed_bound = LZ4_compressBound((int)block_size);
    uint8_t *output_buf = (uint8_t *)malloc((size_t)compressed_bound);
    if (!input_buf || !output_buf) {
        free(input_buf); free(output_buf);
        return -1;
    }

    XXH32_state_t content_hash;
    XXH32_reset(&content_hash, 0);

    while (1) {
        size_t n = fread(input_buf, 1, block_size, in);
        if (n == 0) break;
        *bytes_read += n;

        if (prefs->content_checksum) {
            XXH32_update(&content_hash, input_buf, n);
        }

        int cs = LZ4_compress_default((const char *)input_buf, (char *)output_buf, (int)n, compressed_bound);
        uint8_t sz_buf[4];
        const uint8_t *block_data;
        size_t block_len;
        if (cs > 0 && (size_t)cs < n) {
            write_le32(sz_buf, (uint32_t)cs);
            block_data = output_buf;
            block_len = (size_t)cs;
        } else {
            write_le32(sz_buf, (uint32_t)n | 0x80000000U);
            block_data = input_buf;
            block_len = n;
        }
        if (fwrite(sz_buf, 1, 4, out) != 4) { free(input_buf); free(output_buf); return -1; }
        *bytes_written += 4;
        if (fwrite(block_data, 1, block_len, out) != block_len) { free(input_buf); free(output_buf); return -1; }
        *bytes_written += block_len;
        if (prefs->block_checksum) {
            uint32_t bcs = XXH32(block_data, block_len, 0);
            uint8_t bc_buf[4];
            write_le32(bc_buf, bcs);
            if (fwrite(bc_buf, 1, 4, out) != 4) { free(input_buf); free(output_buf); return -1; }
            *bytes_written += 4;
        }
        if (n < block_size) break;
    }

    /* EndMark */
    uint8_t endmark[4] = {0,0,0,0};
