    XXH32_reset(&content_hash, 0);

    while (1) {
        size_t n = fread(input_buf, 1, block_size, in);
        if (n == 0) break;
        *bytes_read += n;

        if (prefs->content_checksum) {
            XXH32_update(&content_hash, input_buf, n);
        }

        int cs = LZ4_compress_default((const char *)input_buf, (char *)output_buf, (int)n, compressed_bound);
        uint8_t sz_buf[4];
        const uint8_t *block_data;
        size_t block_len;
        if (cs > 0 && (size_t)cs < n) {
            write_le32(sz_buf, (uint32_t)cs);
            block_data = output_buf;
            block_len = (size_t)cs;
        } else {
            write_le32(sz_buf, (uint32_t)n | 0x80000000U);
            block_data = input_buf;
            block_len = n;
        }
        if (fwrite(sz_buf, 1, 4, out) != 4) { free(input_buf); free(output_buf); return -1; }
        *bytes_written += 4;
        if (fwrite(block_data, 1, block_len, out) != block_len) { free(input_buf); free(output_buf); return -1; }
        *bytes_written += block_len;
        if (prefs->block_checksum) {
            uint32_t bcs = XXH32(block_data, block_len, 0);
            uint8_t bc_buf[4];
            write_le32(bc_buf, bcs);
            if (fwrite(bc_buf, 1, 4, out) != 4) { free(input_buf); free(output_buf); return -1; }
            *bytes_written += 4;
        }
        if (n < block_size) break;
    }

    /* EndMark */
    uint8_t endmark[4] = {0,0,0,0};
    if (fwrite(endmark, 1, 4, out) != 4) { free(input_buf); free(output_buf); return -1; }
    *bytes_written += 4;

    if (prefs->content_checksum) {
        uint32_t cc = XXH32_digest(&content_hash);
        uint8_t cc_buf[4];
        write_le32(cc_buf, cc);
        if (fwrite(cc_buf, 1, 4, out) != 4) { free(input_buf); free(output_buf); return -1; }
        *bytes_written += 4;
    }

    free(input_buf);
    free(output_buf);
    return 0;
}

/* Read helper */
static int readn(FILE *f, void *buf, size_t n) {
    size_t r = fread(buf, 1, n, f);
    return r == n ? 0 : -1;
}

static int decompress_frame(FILE *in, FILE *out,
                            uint64_t *bytes_read, uint64_t *bytes_written,
                            uint32_t first_magic) {
    uint8_t flg_bd[2];
    if (readn(in, flg_bd, 2) != 0) return -1;
    *bytes_read += 2;
    uint8_t flg = flg_bd[0];
    uint8_t bd = flg_bd[1];

    int version = (flg >> 6) & 0x3;
    if (version != 1) return -1;

    int block_indep = (flg >> 5) & 1;
    int block_checksum = (flg >> 4) & 1;
    int content_size_flag = (flg >> 3) & 1;
    int content_checksum_flag = (flg >> 2) & 1;
    int dict_id_flag = flg & 1;
    int block_size_id = (bd >> 4) & 0x7;
    (void)block_indep;

    uint8_t header_extra[12];
    size_t extra_pos = 0;
    uint64_t frame_content_size = 0;
    if (content_size_flag) {
        if (readn(in, header_extra + extra_pos, 8) != 0) return -1;
        *bytes_read += 8;
        for (int i = 0; i < 8; i++) frame_content_size |= ((uint64_t)header_extra[extra_pos + i]) << (i*8);
        extra_pos += 8;
    }
    if (dict_id_flag) {
        if (readn(in, header_extra + extra_pos, 4) != 0) return -1;
        *bytes_read += 4;
        extra_pos += 4;
    }

    /* Compute hash of FLG|BD|...|extra for HC verification */
    uint8_t hc_check[2 + 12];
    hc_check[0] = flg;
    hc_check[1] = bd;
    memcpy(hc_check + 2, header_extra, extra_pos);
    uint32_t hc_full = XXH32(hc_check, 2 + extra_pos, 0);
    uint8_t hc_byte;
    if (readn(in, &hc_byte, 1) != 0) return -1;
    *bytes_read += 1;
    if (((hc_full >> 8) & 0xff) != hc_byte) return -1;

    size_t block_size = LZ4F_block_size(block_size_id);
    uint8_t *in_buf = (uint8_t *)malloc(block_size + 16);
    uint8_t *out_buf = (uint8_t *)malloc(block_size);
    if (!in_buf || !out_buf) { free(in_buf); free(out_buf); return -1; }

    XXH32_state_t content_hash;
    XXH32_reset(&content_hash, 0);

    (void)first_magic;
    int ret = 0;

    while (1) {
        uint8_t sz_buf[4];
        if (readn(in, sz_buf, 4) != 0) { ret = -1; break; }
        *bytes_read += 4;
        uint32_t sz = read_le32(sz_buf);
        if (sz == 0) break;  /* EndMark */

        int uncompressed = (sz & 0x80000000U) != 0;
        sz &= 0x7fffffffU;
        if (sz > block_size + 64) { ret = -1; break; }
        if (readn(in, in_buf, sz) != 0) { ret = -1; break; }
        *bytes_read += sz;

        if (block_checksum) {
            uint8_t bck[4];
            if (readn(in, bck, 4) != 0) { ret = -1; break; }
            *bytes_read += 4;
            uint32_t got = XXH32(in_buf, sz, 0);
            uint32_t expect = read_le32(bck);
            if (got != expect) { ret = -1; break; }
        }

        const uint8_t *data;
        size_t data_len;
        if (uncompressed) {
            data = in_buf;
            data_len = sz;
        } else {
            int dec = LZ4_decompress_safe((const char *)in_buf, (char *)out_buf, (int)sz, (int)block_size);
            if (dec < 0) { ret = -1; break; }
            data = out_buf;
            data_len = (size_t)dec;
        }

        if (content_checksum_flag) {
            XXH32_update(&content_hash, data, data_len);
        }
        if (fwrite(data, 1, data_len, out) != data_len) { ret = -1; break; }
        *bytes_written += data_len;
    }

    if (ret == 0 && content_checksum_flag) {
        uint8_t cc_buf[4];
        if (readn(in, cc_buf, 4) != 0) { ret = -1; }
        else {
            *bytes_read += 4;
            uint32_t got = XXH32_digest(&content_hash);
            uint32_t expect = read_le32(cc_buf);
            if (got != expect) ret = -1;
        }
    }

    (void)frame_content_size;
    free(in_buf);
    free(out_buf);
    return ret;
}

int LZ4F_decompress_file(FILE *in, FILE *out,
                         uint64_t *bytes_read,
                         uint64_t *bytes_written,
                         const uint8_t *dict, size_t dict_size,
                         int sparse) {
    (void)dict; (void)dict_size; (void)sparse;
    /* Support multiple concatenated frames and skippable frames */
    while (1) {
        uint8_t magic_buf[4];
        size_t r = fread(magic_buf, 1, 4, in);
        if (r == 0) break;  /* EOF cleanly */
        if (r != 4) return -1;
        *bytes_read += 4;
        uint32_t magic = read_le32(magic_buf);
        if (magic == LZ4F_MAGIC) {
            if (decompress_frame(in, out, bytes_read, bytes_written, magic) != 0) return -1;
        } else if ((magic & 0xfffffff0U) == LZ4F_MAGIC_SKIPPABLE_START) {
            /* Skippable frame */
            uint8_t sz_buf[4];
            if (readn(in, sz_buf, 4) != 0) return -1;
            *bytes_read += 4;
            uint32_t sz = read_le32(sz_buf);
            /* Skip `sz` bytes */
            while (sz > 0) {
                uint8_t tmp[4096];
                size_t want = sz > sizeof(tmp) ? sizeof(tmp) : sz;
                if (readn(in, tmp, want) != 0) return -1;
                *bytes_read += want;
                sz -= (uint32_t)want;
            }
        } else if (magic == LZ4F_LEGACY_MAGIC) {
            if (LZ4F_decompress_legacy_file(in, out, 1, magic, bytes_read, bytes_written) != 0) return -1;
        } else {
            return -1;
        }
    }
    return 0;
}

#define LZ4_LEGACY_BLOCKSIZE (8 * 1024 * 1024)

int LZ4F_compress_legacy_file(FILE *in, FILE *out,
                              uint64_t *bytes_read, uint64_t *bytes_written) {
    uint8_t magic[4];
    write_le32(magic, LZ4F_LEGACY_MAGIC);
    if (fwrite(magic, 1, 4, out) != 4) return -1;
    *bytes_written += 4;

    uint8_t *in_buf = (uint8_t *)malloc(LZ4_LEGACY_BLOCKSIZE);
    int bound = LZ4_compressBound(LZ4_LEGACY_BLOCKSIZE);
    uint8_t *out_buf = (uint8_t *)malloc((size_t)bound);
    if (!in_buf || !out_buf) { free(in_buf); free(out_buf); return -1; }

    while (1) {
        size_t n = fread(in_buf, 1, LZ4_LEGACY_BLOCKSIZE, in);
        if (n == 0) break;
        *bytes_read += n;
        int cs = LZ4_compress_default((const char *)in_buf, (char *)out_buf, (int)n, bound);
        if (cs <= 0) { free(in_buf); free(out_buf); return -1; }
        uint8_t sz[4];
        write_le32(sz, (uint32_t)cs);
        if (fwrite(sz, 1, 4, out) != 4) { free(in_buf); free(out_buf); return -1; }
        *bytes_written += 4;
        if (fwrite(out_buf, 1, (size_t)cs, out) != (size_t)cs) { free(in_buf); free(out_buf); return -1; }
        *bytes_written += (size_t)cs;
        if (n < LZ4_LEGACY_BLOCKSIZE) break;
    }

    free(in_buf);
    free(out_buf);
    return 0;
}

int LZ4F_decompress_legacy_file(FILE *in, FILE *out, int magic_already_read,
                                uint32_t magic,
                                uint64_t *bytes_read, uint64_t *bytes_written) {
    (void)magic;
    if (!magic_already_read) {
        uint8_t magic_buf[4];
        if (readn(in, magic_buf, 4) != 0) return -1;
        *bytes_read += 4;
        if (read_le32(magic_buf) != LZ4F_LEGACY_MAGIC) return -1;
    }
    uint8_t *in_buf = (uint8_t *)malloc(LZ4_LEGACY_BLOCKSIZE + 16);
    uint8_t *out_buf = (uint8_t *)malloc(LZ4_LEGACY_BLOCKSIZE);
    if (!in_buf || !out_buf) { free(in_buf); free(out_buf); return -1; }

    while (1) {
        uint8_t sz_buf[4];
        size_t r = fread(sz_buf, 1, 4, in);
        if (r == 0) break;
        if (r != 4) { free(in_buf); free(out_buf); return -1; }
        *bytes_read += 4;
        uint32_t sz = read_le32(sz_buf);
        /* Legacy frames can be followed by another legacy frame magic; not all sizes are blocks */
        if (sz == LZ4F_LEGACY_MAGIC || sz == LZ4F_MAGIC) {
            /* Rewind: we read the next frame's magic; handle by putting back into stream with ungetc (tricky) */
            /* Simple approach: if stream is seekable, seek back 4. */
            if (fseek(in, -4, SEEK_CUR) != 0) { free(in_buf); free(out_buf); return -1; }
            *bytes_read -= 4;
            break;
        }
        if (sz > LZ4_LEGACY_BLOCKSIZE + 64) { free(in_buf); free(out_buf); return -1; }
        if (readn(in, in_buf, sz) != 0) { free(in_buf); free(out_buf); return -1; }
        *bytes_read += sz;
        int dec = LZ4_decompress_safe((const char *)in_buf, (char *)out_buf, (int)sz, LZ4_LEGACY_BLOCKSIZE);
        if (dec < 0) { free(in_buf); free(out_buf); return -1; }
        if (fwrite(out_buf, 1, (size_t)dec, out) != (size_t)dec) { free(in_buf); free(out_buf); return -1; }
        *bytes_written += (size_t)dec;
        if (dec < LZ4_LEGACY_BLOCKSIZE) break;
    }

    free(in_buf);
    free(out_buf);
    return 0;
}

int LZ4F_list_file(const char *filename) {
    (void)filename;
    return 0;
}
