/* Parse an integer starting at *pp, advance *pp past it, store in *v. Returns 1 if ok */
static int parse_int(const char **pp, int *v) {
    const char *p = *pp;
    if (!isdigit((unsigned char)*p)) return 0;
    int x = 0;
    while (isdigit((unsigned char)*p)) {
        x = x * 10 + (*p - '0');
        p++;
    }
    *v = x;
    *pp = p;
    return 1;
}

/* Format: ask user y/N prompt */
static int ask_overwrite(const char *path) {
    fprintf(stderr, "%s already exists; do you want to overwrite (y/N) ? ", path);
