}

/* Compress a single input to output.
 * in_path: may be NULL for stdin (or "stdin"); out_path: may be NULL for stdout.
 */
static int compress_one(const char *in_path, const char *out_path, const options_t *opt,
                        const uint8_t *dict, size_t dict_size) {
    FILE *in;
    uint64_t content_size = 0;
    int have_size = 0;

    if (in_path == NULL || strcmp(in_path, "-") == 0 || strcmp(in_path, "stdin") == 0) {
        in = stdin;
    } else {
        struct stat st;
        if (stat(in_path, &st) != 0) {
            fprintf(stderr, "%s: No such file or directory \n", in_path);
            return 1;
        }
        if (S_ISDIR(st.st_mode)) {
            fprintf(stderr, "lz4: %s is a directory -- ignored \n", in_path);
            return 1;
        }
        in = fopen(in_path, "rb");
        if (!in) {
            fprintf(stderr, "%s: %s \n", in_path, strerror(errno));
            return 1;
        }
        content_size = (uint64_t)st.st_size;
        have_size = 1;
    }

    FILE *out;
    int out_is_null = 0;
    if (out_path == NULL || strcmp(out_path, "-") == 0 || strcmp(out_path, "stdout") == 0) {
        out = stdout;
    } else if (strcmp(out_path, "null") == 0) {
        out = fopen("/dev/null", "wb");
        out_is_null = 1;
    } else {
        out = fopen(out_path, "wb");
    }
    if (!out) {
        fprintf(stderr, "%s: %s\n", out_path ? out_path : "stdout", strerror(errno));
        if (in != stdin) fclose(in);
        return 1;
    }

    uint64_t bytes_read = 0, bytes_written = 0;
    int rc;
    if (opt->legacy) {
        rc = LZ4F_compress_legacy_file(in, out, &bytes_read, &bytes_written);
    } else {
        LZ4F_prefs_t prefs;
        memset(&prefs, 0, sizeof(prefs));
        prefs.block_size_id = opt->block_size_id;
        prefs.block_mode = opt->block_indep;
        prefs.block_checksum = opt->block_checksum;
        prefs.content_checksum = opt->no_frame_crc ? 0 : 1;
        prefs.content_size = opt->content_size;
        prefs.compression_level = opt->level;
        prefs.favor_dec_speed = opt->favor_dec_speed;
        rc = LZ4F_compress_file(in, out, &prefs, have_size ? content_size : 0,
                                &bytes_read, &bytes_written, dict, dict_size);
    }

    if (in != stdin) fclose(in);
    if (out != stdout) {
        fflush(out);
        fclose(out);
    } else {
        fflush(out);
    }

    if (rc != 0) {
        if (out_path && out != stdout && !out_is_null) unlink(out_path);
        return 1;
    }

    if (opt->quiet == 0) {
        const char *disp_in = in_path ? in_path : "stdin";
        double ratio = (bytes_read > 0) ? (100.0 * (double)bytes_written / (double)bytes_read) : 0.0;
        fprintf(stderr, "\rRead : %lu MiB   ==> %.2f%%   \r%79s\rCompressed %lu bytes into %lu bytes ==> %.2f%%\n",
                (unsigned long)(bytes_read >> 20),
                ratio,
                "",
                (unsigned long)bytes_read, (unsigned long)bytes_written,
                ratio);
        (void)disp_in;
    }

    if (opt->remove_src && in_path && in != stdin) {
        unlink(in_path);
    }

    return 0;
}

/* Decompress one file */
static int decompress_one(const char *in_path, const char *out_path, const options_t *opt,
                          const uint8_t *dict, size_t dict_size, int test_mode) {
    FILE *in;
    if (in_path == NULL || strcmp(in_path, "-") == 0 || strcmp(in_path, "stdin") == 0) {
        in = stdin;
    } else {
        struct stat st;
        if (stat(in_path, &st) != 0) {
            fprintf(stderr, "%s: No such file or directory \n", in_path);
            return 1;
        }
        in = fopen(in_path, "rb");
        if (!in) {
            fprintf(stderr, "%s: %s \n", in_path, strerror(errno));
            return 1;
        }
    }

    FILE *out;
    int out_is_null = 0;
    if (test_mode) {
        out = fopen("/dev/null", "wb");
        out_is_null = 1;
    } else if (out_path == NULL || strcmp(out_path, "-") == 0 || strcmp(out_path, "stdout") == 0) {
        out = stdout;
    } else if (strcmp(out_path, "null") == 0) {
        out = fopen("/dev/null", "wb");
        out_is_null = 1;
    } else {
        out = fopen(out_path, "wb");
    }
    if (!out) {
        fprintf(stderr, "%s: %s\n", out_path ? out_path : "stdout", strerror(errno));
        if (in != stdin) fclose(in);
        return 1;
    }

    uint64_t bytes_read = 0, bytes_written = 0;
    int rc = LZ4F_decompress_file(in, out, &bytes_read, &bytes_written,
                                  dict, dict_size, opt->use_sparse);
    if (in != stdin) fclose(in);
    if (out != stdout) {
        fflush(out);
        fclose(out);
    } else {
        fflush(out);
    }

    if (rc != 0) {
        if (opt->quiet < 2) {
            fprintf(stderr, "Error 44 : Unrecognized header : file cannot be decoded \n");
        }
        if (out_path && out != stdout && !out_is_null && !test_mode) unlink(out_path);
        return 44;
    }

    if (opt->quiet == 0) {
        const char *disp_in = in_path ? in_path : "stdin";
        fprintf(stderr, "\rDecompressed : %lu MiB  \r%79s\r",
                (unsigned long)(bytes_written >> 20), "");
        print_filename_pad(stderr, disp_in);
        fprintf(stderr, ": decoded %lu bytes \n", (unsigned long)bytes_written);
    }

    if (opt->remove_src && !test_mode && in_path && in != stdin) {
        unlink(in_path);
    }

    return 0;
}

/* Determine default output path for compression */
static char *default_compress_out(const char *in_path) {
    size_t n = strlen(in_path);
    char *out = (char *)malloc(n + 5);
    sprintf(out, "%s.lz4", in_path);
    return out;
}

/* Determine default output path for decompression (strip .lz4) */
static char *default_decompress_out(const char *in_path) {
    size_t n = strlen(in_path);
    if (n >= 4 && strcmp(in_path + n - 4, ".lz4") == 0) {
        char *out = (char *)malloc(n - 3);
        memcpy(out, in_path, n - 4);
        out[n - 4] = '\0';
        return out;
    }
    /* Has no .lz4 ext */
    return NULL;
}

/* List mode */
static int list_file(const char *path, int header_done) {
    if (!header_done) {
        printf("    Frames           Type Block  Compressed  Uncompressed    Ratio   Filename\n");
    }
    struct stat st;
    if (stat(path, &st) != 0 || !S_ISREG(st.st_mode)) {
        fprintf(stderr, "lz4: %s is not a regular file \n", path);
        return 1;
    }
    FILE *f = fopen(path, "rb");
    if (!f) return 1;

    uint8_t magic[4];
    size_t frames = 0;
    const char *type = "LZ4Frame";
    char block[8] = "B4I";
    size_t total_compressed = (size_t)st.st_size;
    uint64_t total_uncompressed = 0;
    int unknown_uncompressed = 0;

    while (1) {
        size_t r = fread(magic, 1, 4, f);
        if (r == 0) break;
        if (r != 4) { fclose(f); return 1; }
        uint32_t m = (uint32_t)magic[0] | ((uint32_t)magic[1]<<8) | ((uint32_t)magic[2]<<16) | ((uint32_t)magic[3]<<24);
        if (m == LZ4F_MAGIC) {
            frames++;
            uint8_t flg, bd;
            if (fread(&flg, 1, 1, f) != 1) { fclose(f); return 1; }
            if (fread(&bd, 1, 1, f) != 1) { fclose(f); return 1; }
            int block_indep = (flg >> 5) & 1;
            int block_checksum = (flg >> 4) & 1;
            int content_size_flag = (flg >> 3) & 1;
            int content_checksum_flag = (flg >> 2) & 1;
            int dict_id_flag = flg & 1;
            int block_size_id = (bd >> 4) & 7;
            sprintf(block, "B%d%c%s", block_size_id, block_indep ? 'I' : 'D', block_checksum ? "X" : "");
            (void)content_checksum_flag;
            if (content_size_flag) {
                uint8_t sz[8];
                if (fread(sz, 1, 8, f) != 8) { fclose(f); return 1; }
                uint64_t cs = 0;
                for (int i = 0; i < 8; i++) cs |= ((uint64_t)sz[i]) << (i*8);
                total_uncompressed += cs;
            } else {
                unknown_uncompressed = 1;
            }
            if (dict_id_flag) {
                uint8_t d[4];
                if (fread(d, 1, 4, f) != 4) { fclose(f); return 1; }
            }
            uint8_t hc;
            if (fread(&hc, 1, 1, f) != 1) { fclose(f); return 1; }
            /* Skip blocks */
            while (1) {
                uint8_t sz_buf[4];
                if (fread(sz_buf, 1, 4, f) != 4) { fclose(f); return 1; }
                uint32_t sz = (uint32_t)sz_buf[0] | ((uint32_t)sz_buf[1]<<8) | ((uint32_t)sz_buf[2]<<16) | ((uint32_t)sz_buf[3]<<24);
                if (sz == 0) break;
                sz &= 0x7fffffffU;
                if (fseek(f, sz, SEEK_CUR) != 0) { fclose(f); return 1; }
                if (block_checksum) {
                    uint8_t bc[4];
                    if (fread(bc, 1, 4, f) != 4) { fclose(f); return 1; }
                }
            }
            if (content_checksum_flag) {
                uint8_t cc[4];
                if (fread(cc, 1, 4, f) != 4) { fclose(f); return 1; }
            }
        } else {
            fclose(f);
            return 1;
        }
    }

    fclose(f);

    /* Derive filename base */
    const char *fname = strrchr(path, '/');
    fname = fname ? fname + 1 : path;

    if (unknown_uncompressed) {
        printf("%10zu       %s   %-3s  %10.2f             -        -   %s\n",
               frames, type, block, (double)total_compressed, fname);
    } else {
        double ratio = total_uncompressed > 0 ? (double)total_compressed / (double)total_uncompressed : 0.0;
        printf("%10zu       %s   %-3s  %10.2f  %12lu  %.4f   %s\n",
               frames, type, block, (double)total_compressed,
               (unsigned long)total_uncompressed, ratio, fname);
    }

    return 0;
}

int main(int argc, char **argv) {
    options_t opt;
    init_options(&opt);

    int mode = MODE_COMPRESS;
    int forced_mode_set = 0;

    /* First scan: determine program name from argv[0] to change defaults */
    const char *bn = strrchr(argv[0], '/');
    bn = bn ? bn + 1 : argv[0];
    if (strstr(bn, "unlz4") != NULL) {
        mode = MODE_DECOMPRESS;
        opt.forced_mode = 1;
        forced_mode_set = 1;
    } else if (strstr(bn, "lz4cat") != NULL) {
        mode = MODE_DECOMPRESS;
        opt.forced_mode = 1;
        forced_mode_set = 1;
        opt.force_stdout = 1;
        opt.multiple = 1;
        opt.force_overwrite = 1;
    }
    (void)forced_mode_set;

    /* Collect positional args */
    const char **positional = (const char **)calloc((size_t)argc + 1, sizeof(char *));
    int npos = 0;
    int force_stdin = 0;
    const char *dict_arg = NULL;

    for (int i = 1; i < argc; i++) {
        const char *arg = argv[i];
        if (arg[0] == '-' && arg[1] != '\0') {
            int r = parse_option(arg, &opt, &mode, &force_stdin);
            if (r == -1) {
                fprintf(stderr, "Incorrect parameters\n");
                print_usage_short(stderr);
                free(positional);
                return 1;
            }
            if (r == 1) {
                /* It was a bare "-" meaning stdin */
                positional[npos++] = "-";
            }
            if (r == 2) {
                /* Need next arg for dict file */
                if (i + 1 >= argc) {
                    fprintf(stderr, "Incorrect parameters\n");
                    print_usage_short(stderr);
                    free(positional);
                    return 1;
                }
                dict_arg = argv[++i];
            }
        } else {
            positional[npos++] = arg;
        }
    }

    if (dict_arg && !opt.dict_file) opt.dict_file = dict_arg;

    /* If a --list mode was set, list the files */
    if (mode == MODE_LIST) {
        int rc = 0;
        if (npos == 0) {
            fprintf(stderr, "lz4: --list requires at least one filename \n");
            free(positional);
            return 1;
        }
        /* Print header */
        printf("    Frames           Type Block  Compressed  Uncompressed    Ratio   Filename\n");
        for (int i = 0; i < npos; i++) {
            if (list_file(positional[i], 1) != 0) rc = 1;
        }
        free(positional);
        return rc;
    }

    /* Dict file load */
    uint8_t *dict_data = NULL;
    size_t dict_size = 0;
    if (opt.dict_file) {
        dict_data = load_dict(opt.dict_file, &dict_size);
        if (!dict_data) {
            fprintf(stderr, "%s: %s \n", opt.dict_file, strerror(errno));
            free(positional);
            return 1;
        }
    }

    /* Benchmark mode - minimal stub */
    if (mode == MODE_BENCHMARK) {
        /* Stub: just exit 0 since we can't easily implement this from scratch */
        free(positional);
        free(dict_data);
        return 0;
    }

    /* Auto-detect mode from input name if not forced */
    if (!opt.forced_mode) {
        if (npos >= 1 && has_lz4_ext(positional[0])) {
            mode = MODE_DECOMPRESS;
        }
    }

    /* Determine input/output */
    const char *input = NULL;
    const char *output = NULL;

    if (opt.multiple || mode == MODE_TEST) {
        /* Process each file individually */
        int rc = 0;
        if (npos == 0) {
            /* Use stdin */
            positional[0] = "-";
            npos = 1;
        }
        for (int i = 0; i < npos; i++) {
            const char *in = positional[i];
            if (mode == MODE_TEST) {
                if (decompress_one(in, NULL, &opt, dict_data, dict_size, 1) != 0) rc = 1;
            } else if (mode == MODE_DECOMPRESS) {
                char *out = NULL;
                if (opt.force_stdout) {
                    out = NULL;
                } else {
                    out = default_decompress_out(in);
                    if (!out) {
                        fprintf(stderr, "%s: unknown suffix -- ignored \n", in);
                        rc = 1;
                        continue;
                    }
                    if (file_exists(out) && !opt.force_overwrite) {
                        fprintf(stderr, "%s already exists; not overwritten  \n", out);
                        rc = 2;
                        free(out);
                        continue;
                    }
                }
                int r = decompress_one(in, opt.force_stdout ? NULL : out, &opt, dict_data, dict_size, 0);
                if (r != 0) rc = r;
                free(out);
            } else {
                /* MODE_COMPRESS */
                char *out = NULL;
                if (opt.force_stdout) {
                    out = NULL;
                } else {
                    out = default_compress_out(in);
                    if (file_exists(out) && !opt.force_overwrite) {
                        fprintf(stderr, "%s already exists; not overwritten  \n", out);
                        rc = 2;
                        free(out);
                        continue;
                    }
                }
                int r = compress_one(in, opt.force_stdout ? NULL : out, &opt, dict_data, dict_size);
                if (r != 0) rc = r;
                free(out);
            }
        }
        free(positional);
        free(dict_data);
        return rc;
    }

    /* Single input/output mode */
    if (npos == 0) {
        input = NULL;  /* stdin */
    } else if (npos == 1) {
        input = positional[0];
    } else if (npos == 2) {
        input = positional[0];
        output = positional[1];
    } else {
        fprintf(stderr, "Error : %s won't be used ! Do you want multiple input files (-m) ? \n",
                positional[2]);
        free(positional);
        free(dict_data);
        return 1;
    }

    /* Determine output */
    char *default_out = NULL;
    if (!output) {
        if (opt.force_stdout) {
            output = NULL;  /* stdout */
        } else if (!isatty(fileno(stdout))) {
            /* stdout is a pipe/file - use stdout */
            output = NULL;
        } else {
            /* stdout is console */
            if (input == NULL) {
                fprintf(stderr, "Cannot determine an output filename \n");
                fprintf(stderr, "Incorrect parameters\n");
                print_usage_short(stderr);
                free(positional);
                free(dict_data);
                return 1;
            }
            if (mode == MODE_COMPRESS) {
                default_out = default_compress_out(input);
                output = default_out;
                if (opt.quiet == 0) {
                    fprintf(stderr, "Compressed filename will be : %s \n", output);
                }
            } else if (mode == MODE_DECOMPRESS) {
                default_out = default_decompress_out(input);
                if (!default_out) {
                    fprintf(stderr, "Cannot determine an output filename \n");
                    fprintf(stderr, "Incorrect parameters\n");
                    print_usage_short(stderr);
                    free(positional);
                    free(dict_data);
                    return 1;
                }
                output = default_out;
                if (opt.quiet == 0) {
                    fprintf(stderr, "Decoding file %s \n", output);
                }
            }
        }
    }

    /* Check overwrite */
    if (output && file_exists(output) && !opt.force_overwrite) {
        /* Check if writing to a device file (/dev/null, stdout, etc.) */
        struct stat st;
        if (stat(output, &st) == 0 && S_ISREG(st.st_mode)) {
            if (isatty(fileno(stdin))) {
                fprintf(stderr, "%s already exists; not overwritten  \n", output);
                free(positional);
                free(default_out);
                free(dict_data);
                return 2;
            } else {
                if (!ask_overwrite(output)) {
                    fprintf(stderr, "    not overwritten  \n");
                    free(positional);
                    free(default_out);
                    free(dict_data);
                    return 2;
                }
            }
        }
    }

    int rc;
    if (mode == MODE_DECOMPRESS) {
        rc = decompress_one(input, output, &opt, dict_data, dict_size, 0);
    } else if (mode == MODE_TEST) {
        rc = decompress_one(input, NULL, &opt, dict_data, dict_size, 1);
    } else {
        rc = compress_one(input, output, &opt, dict_data, dict_size);
    }

    free(positional);
    free(default_out);
    free(dict_data);
    return rc;
}
