#define LZ4_VERSION_STR "1.10.0"

static const char *program_name = "executable";

enum mode {
    MODE_COMPRESS,
    MODE_DECOMPRESS,
    MODE_TEST,
    MODE_LIST,
    MODE_BENCHMARK,
};

typedef struct {
    int verbose;
    int quiet;            /* -q count */
    int force_overwrite;
    int force_stdout;
    int multiple;
    int recursive;
    int keep;             /* keep source files (default 1) */
    int remove_src;
    int legacy;           /* -l */
    int use_sparse;
    int sparse_set;
    int content_size;
    int no_frame_crc;
    int block_checksum;
