    int forced_mode;      /* 1 if -d or -z explicitly set */
} options_t;

static void print_version(FILE *f) {
    fprintf(f, "*** lz4 v%s 64-bit multithread, by Yann Collet ***\n", LZ4_VERSION_STR);
}

static void print_usage_short(FILE *f) {
    fprintf(f,
        "Usage : \n"
        "      %s [arg] [input] [output] \n"
        "\n"
        "input   : a filename \n"
        "          with no FILE, or when FILE is - or stdin, read standard input\n"
        "Arguments : \n"
        " -1     : fast compression (default) \n"
        " -12    : slowest compression level \n"
        " -T#    : use # threads for compression (default:0==auto) \n"
        " -d     : decompression (default for .lz4 extension)\n"
        " -f     : overwrite output without prompting \n"
        " -k     : preserve source files(s)  (default) \n"
        "--rm    : remove source file(s) after successful de/compression \n"
        " -h/-H  : display help/long help and exit \n",
        program_name);
}

static void print_usage_adv(FILE *f) {
    fprintf(f,
        "\n"
        "Advanced arguments :\n"
        " -V     : display Version number and exit \n"
        " -v     : verbose mode \n"
        " -q     : suppress warnings; specify twice to suppress errors too\n"
        " -c     : force write to standard output, even if it is the console\n"
        " -t     : test compressed file integrity\n"
        " -m     : multiple input files (implies automatic output filenames)\n"
        " -r     : operate recursively on directories (sets also -m) \n"
        " -l     : compress using Legacy format (Linux kernel compression)\n"
        " -z     : force compression \n"
        " -D FILE: use FILE as dictionary (compression & decompression)\n"
        " -B#    : cut file into blocks of size # bytes [32+] \n"
        "                     or predefined block size [4-7] (default: 7) \n"
        " -BI    : Block Independence (default) \n"
        " -BD    : Block dependency (improves compression ratio) \n"
        " -BX    : enable block checksum (default:disabled) \n"
        "--no-frame-crc : disable stream checksum (default:enabled) \n"
        "--content-size : compressed frame includes original size (default:not present)\n"
        "--list FILE : lists information about .lz4 files (useful for files compressed with --content-size flag)\n"
        "--[no-]sparse  : sparse mode (default:enabled on file, disabled on stdout)\n"
        "--favor-decSpeed: compressed files decompress faster, but are less compressed \n"
        "--fast[=#]: switch to ultra fast compression level (default: 1)\n"
        "--best  : same as -12\n"
        "Benchmark arguments : \n"
        " -b#    : benchmark file(s), using # compression level (default : 1) \n"
        " -e#    : test all compression levels from -bX to # (default : 1)\n"
        " -i#    : minimum evaluation time in seconds (default : 3s) \n");
}

static void print_long_help(FILE *f) {
    fprintf(f,
        "\n"
        "****************************\n"
        "***** Advanced comment *****\n"
        "****************************\n"
        "\n"
        "Which values can [output] have ? \n"
        "---------------------------------\n"
        "[output] : a filename \n"
        "          'stdout', or '-' for standard output (pipe mode)\n"
        "          'null' to discard output (test mode) \n"
        "[output] can be left empty. In this case, it receives the following value :\n"
        "          - if stdout is not the console, then [output] = stdout \n"
        "          - if stdout is console : \n"
        "               + for compression, output to filename.lz4 \n"
        "               + for decompression, output to filename without '.lz4'\n"
        "                    > if input filename has no '.lz4' extension : error \n"
        "\n"
        "Compression levels : \n"
        "---------------------\n"
        "-0  => Default level, identical to -1 \n"
        "-1  => Fast compression \n"
        "-2 .. -12 => High compression; higher number == more compression but slower\n"
        "--best    => Highest available compression level (-12) \n"
        "--fast=#  => Faster compression; higher number == faster but compress less\n"
        "\n"
        "stdin, stdout and the console : \n"
        "--------------------------------\n"
        "To protect the console from binary flooding (bad argument mistake)\n"
        "%s will refuse to read from console, or write to console \n"
        "except if '-c' command is specified, to force output to console \n"
        "\n"
        "Simple example :\n"
        "----------------\n"
        "1 : compress 'filename' fast, using default output name 'filename.lz4'\n"
        "          %s filename\n"
        "\n"
        "Short arguments can be aggregated. For example :\n"
        "----------------------------------\n"
        "2 : compress 'filename' in high compression mode, overwrite output if exists\n"
        "          %s -9 -f filename \n"
        "    is equivalent to :\n"
        "          %s -9f filename \n"
        "\n"
        "%s can be used in 'pure pipe mode'. For example :\n"
        "-------------------------------------\n"
        "3 : compress data stream from 'generator', send result to 'consumer'\n"
        "          generator | %s | consumer \n",
        program_name, program_name, program_name, program_name,
        program_name, program_name);
}

static void init_options(options_t *opt) {
    memset(opt, 0, sizeof(*opt));
    opt->keep = 1;
    opt->level = 1;
    opt->block_size_id = 7;
    opt->block_indep = 1;
    opt->bench_iterations = 3;
    opt->threads = 0;
}

static int has_lz4_ext(const char *name) {
    size_t n = strlen(name);
    return (n >= 4) && strcmp(name + n - 4, ".lz4") == 0;
}

static int is_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return 0;
    return S_ISDIR(st.st_mode);
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

/* Parse an integer starting at *pp, advance *pp past it, store in *v. Returns 1 if ok */
static int parse_int(const char **pp, int *v) {
    const char *p = *pp;
    if (!isdigit((unsigned char)*p)) return 0;
    int x = 0;
    while (isdigit((unsigned char)*p)) {
        x = x * 10 + (*p - '0');
        p++;
    }
    *v = x;
    *pp = p;
    return 1;
}

/* Format: ask user y/N prompt */
static int ask_overwrite(const char *path) {
    fprintf(stderr, "%s already exists; do you want to overwrite (y/N) ? ", path);
    fflush(stderr);
    char buf[16];
    if (fgets(buf, sizeof(buf), stdin) == NULL) return 0;
    if (buf[0] == 'y' || buf[0] == 'Y') return 1;
    return 0;
}

/* ============ Dictionary loading ============ */
static uint8_t *load_dict(const char *path, size_t *out_size) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (sz < 0) { fclose(f); return NULL; }
    uint8_t *buf = (uint8_t *)malloc((size_t)sz + 1);
    if (!buf) { fclose(f); return NULL; }
    if (fread(buf, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(buf); return NULL; }
    fclose(f);
    *out_size = (size_t)sz;
    return buf;
}

/* ============ CLI argument parsing ============ */

static int process_arg_letter(char c, const char **rest, options_t *opt, int *mode, int *force_stdin);

/* Parse a single option argument that starts with - */
static int parse_option(const char *arg, options_t *opt, int *mode, int *force_stdin) {
    /* Long options */
    if (arg[0] == '-' && arg[1] == '-') {
        const char *lopt = arg + 2;
        if (strcmp(lopt, "help") == 0) {
            print_version(stdout);
            print_usage_short(stdout);
            print_usage_adv(stdout);
            exit(0);
        }
        if (strcmp(lopt, "version") == 0) {
            print_version(stdout);
            exit(0);
        }
        if (strcmp(lopt, "compress") == 0) { *mode = MODE_COMPRESS; opt->forced_mode = 1; return 0; }
        if (strcmp(lopt, "decompress") == 0 || strcmp(lopt, "uncompress") == 0) {
            *mode = MODE_DECOMPRESS; opt->forced_mode = 1; return 0;
        }
        if (strcmp(lopt, "test") == 0) { *mode = MODE_TEST; return 0; }
        if (strcmp(lopt, "force") == 0) { opt->force_overwrite = 1; return 0; }
        if (strcmp(lopt, "stdout") == 0 || strcmp(lopt, "to-stdout") == 0) {
            opt->force_stdout = 1; opt->keep = 1; return 0;
        }
        if (strcmp(lopt, "rm") == 0) { opt->remove_src = 1; opt->keep = 0; return 0; }
        if (strcmp(lopt, "keep") == 0) { opt->keep = 1; opt->remove_src = 0; return 0; }
        if (strcmp(lopt, "quiet") == 0) { opt->quiet++; return 0; }
        if (strcmp(lopt, "verbose") == 0) { opt->verbose++; return 0; }
        if (strcmp(lopt, "multiple") == 0) { opt->multiple = 1; return 0; }
        if (strcmp(lopt, "recursive") == 0) { opt->recursive = 1; opt->multiple = 1; return 0; }
        if (strcmp(lopt, "list") == 0) { *mode = MODE_LIST; opt->multiple = 1; return 0; }
        if (strcmp(lopt, "sparse") == 0) { opt->use_sparse = 1; opt->sparse_set = 1; return 0; }
        if (strcmp(lopt, "no-sparse") == 0) { opt->use_sparse = 0; opt->sparse_set = 1; return 0; }
        if (strcmp(lopt, "no-frame-crc") == 0) { opt->no_frame_crc = 1; return 0; }
        if (strcmp(lopt, "content-size") == 0) { opt->content_size = 1; return 0; }
        if (strcmp(lopt, "no-content-size") == 0) { opt->content_size = 0; return 0; }
        if (strcmp(lopt, "frame-crc") == 0) { opt->no_frame_crc = 0; return 0; }
        if (strcmp(lopt, "best") == 0) { opt->level = 12; return 0; }
        if (strcmp(lopt, "fast") == 0) { opt->level = -1; return 0; }
        if (strncmp(lopt, "fast=", 5) == 0) {
            int v = atoi(lopt + 5);
            if (v < 1) v = 1;
            opt->level = -v;
            return 0;
        }
        if (strcmp(lopt, "favor-decSpeed") == 0) { opt->favor_dec_speed = 1; return 0; }
        if (strcmp(lopt, "long") == 0 || strcmp(lopt, "help-long") == 0) { /* ignore */ return 0; }
        fprintf(stderr, "Unrecognized option: %s\n", arg);
        return -1;
    }

    /* Short options (aggregated) */
    const char *p = arg + 1;
    if (*p == '\0') {
        /* "-" means stdin */
        *force_stdin = 1;
        return 1;  /* signal: treat as input argument */
    }
    while (*p) {
        char c = *p++;
        if (c >= '0' && c <= '9') {
            const char *q = p - 1;
            int v = 0;
            if (!parse_int(&q, &v)) return -1;
            p = q;
            opt->level = v;
            continue;
        }
        switch (c) {
            case 'V':
                print_version(stdout);
                exit(0);
            case 'h':
                print_version(stdout);
                print_usage_short(stdout);
                print_usage_adv(stdout);
                exit(0);
            case 'H':
                print_version(stdout);
                print_usage_short(stdout);
                print_usage_adv(stdout);
                print_long_help(stdout);
                exit(0);
            case 'z': *mode = MODE_COMPRESS; opt->forced_mode = 1; break;
            case 'd': *mode = MODE_DECOMPRESS; opt->forced_mode = 1; break;
            case 't': *mode = MODE_TEST; break;
            case 'f': opt->force_overwrite = 1; break;
            case 'k': opt->keep = 1; opt->remove_src = 0; break;
            case 'c': opt->force_stdout = 1; opt->keep = 1; break;
            case 'm': opt->multiple = 1; break;
            case 'r': opt->recursive = 1; opt->multiple = 1; break;
            case 'v': opt->verbose++; break;
            case 'q': opt->quiet++; break;
            case 'l': opt->legacy = 1; break;
            case 'T': {
                int v = 0;
                if (!parse_int(&p, &v)) return -1;
                opt->threads = v;
                break;
            }
            case 'B': {
                if (*p == 'I') { opt->block_indep = 1; p++; break; }
                if (*p == 'D') { opt->block_indep = 0; p++; break; }
                if (*p == 'X') { opt->block_checksum = 1; p++; break; }
                int v = 0;
                if (!parse_int(&p, &v)) return -1;
                if (v >= 4 && v <= 7) opt->block_size_id = v;
                else if (v >= 32) {
                    /* Compute block size id */
                    if (v <= 64*1024) opt->block_size_id = 4;
                    else if (v <= 256*1024) opt->block_size_id = 5;
                    else if (v <= 1024*1024) opt->block_size_id = 6;
                    else opt->block_size_id = 7;
                } else return -1;
                break;
            }
            case 'D': {
                /* -D FILE or -DFILE */
                if (*p != '\0') {
                    opt->dict_file = p;
                    p += strlen(p);
                }
                /* Else: expect next argument */
                return 2;  /* signal: next argv is dict file */
            }
            case 'b': {
                *mode = MODE_BENCHMARK;
                int v = 1;
                parse_int(&p, &v);
                opt->level = v;
                break;
            }
            case 'e': {
                int v = 1;
                parse_int(&p, &v);
                opt->benchmark_level_end = v;
                break;
            }
            case 'i': {
                int v = 3;
                parse_int(&p, &v);
                opt->bench_iterations = v;
                break;
            }
            default:
                fprintf(stderr, "Unrecognized option: -%c\n", c);
                return -1;
        }
    }
    return 0;
}

/* Print filename padded to 30 chars */
static void print_filename_pad(FILE *f, const char *name) {
    fprintf(f, "%-30s ", name);
}

/* Compress a single input to output.
 * in_path: may be NULL for stdin (or "stdin"); out_path: may be NULL for stdout.
 */
static int compress_one(const char *in_path, const char *out_path, const options_t *opt,
                        const uint8_t *dict, size_t dict_size) {
    FILE *in;
    uint64_t content_size = 0;
    int have_size = 0;

    if (in_path == NULL || strcmp(in_path, "-") == 0 || strcmp(in_path, "stdin") == 0) {
        in = stdin;
    } else {
        struct stat st;
        if (stat(in_path, &st) != 0) {
            fprintf(stderr, "%s: No such file or directory \n", in_path);
            return 1;
        }
        if (S_ISDIR(st.st_mode)) {
            fprintf(stderr, "lz4: %s is a directory -- ignored \n", in_path);
            return 1;
        }
        in = fopen(in_path, "rb");
        if (!in) {
            fprintf(stderr, "%s: %s \n", in_path, strerror(errno));
            return 1;
        }
        content_size = (uint64_t)st.st_size;
        have_size = 1;
    }

    FILE *out;
    int out_is_null = 0;
    if (out_path == NULL || strcmp(out_path, "-") == 0 || strcmp(out_path, "stdout") == 0) {
        out = stdout;
    } else if (strcmp(out_path, "null") == 0) {
        out = fopen("/dev/null", "wb");
        out_is_null = 1;
    } else {
        out = fopen(out_path, "wb");
    }
    if (!out) {
        fprintf(stderr, "%s: %s\n", out_path ? out_path : "stdout", strerror(errno));
        if (in != stdin) fclose(in);
        return 1;
    }

    uint64_t bytes_read = 0, bytes_written = 0;
    int rc;
    if (opt->legacy) {
        rc = LZ4F_compress_legacy_file(in, out, &bytes_read, &bytes_written);
    } else {
        LZ4F_prefs_t prefs;
        memset(&prefs, 0, sizeof(prefs));
        prefs.block_size_id = opt->block_size_id;
        prefs.block_mode = opt->block_indep;
        prefs.block_checksum = opt->block_checksum;
        prefs.content_checksum = opt->no_frame_crc ? 0 : 1;
        prefs.content_size = opt->content_size;
        prefs.compression_level = opt->level;
        prefs.favor_dec_speed = opt->favor_dec_speed;
        rc = LZ4F_compress_file(in, out, &prefs, have_size ? content_size : 0,
                                &bytes_read, &bytes_written, dict, dict_size);
    }

    if (in != stdin) fclose(in);
    if (out != stdout) {
        fflush(out);
        fclose(out);
    } else {
        fflush(out);
    }

    if (rc != 0) {
        if (out_path && out != stdout && !out_is_null) unlink(out_path);
        return 1;
    }

    if (opt->quiet == 0) {
        const char *disp_in = in_path ? in_path : "stdin";
        double ratio = (bytes_read > 0) ? (100.0 * (double)bytes_written / (double)bytes_read) : 0.0;
        fprintf(stderr, "\rRead : %lu MiB   ==> %.2f%%   \r%79s\rCompressed %lu bytes into %lu bytes ==> %.2f%%\n",
                (unsigned long)(bytes_read >> 20),
                ratio,
                "",
                (unsigned long)bytes_read, (unsigned long)bytes_written,
                ratio);
        (void)disp_in;
    }

    if (opt->remove_src && in_path && in != stdin) {
        unlink(in_path);
    }

    return 0;
}

/* Decompress one file */
static int decompress_one(const char *in_path, const char *out_path, const options_t *opt,
                          const uint8_t *dict, size_t dict_size, int test_mode) {
    FILE *in;
    if (in_path == NULL || strcmp(in_path, "-") == 0 || strcmp(in_path, "stdin") == 0) {
        in = stdin;
    } else {
        struct stat st;
        if (stat(in_path, &st) != 0) {
            fprintf(stderr, "%s: No such file or directory \n", in_path);
            return 1;
        }
        in = fopen(in_path, "rb");
        if (!in) {
            fprintf(stderr, "%s: %s \n", in_path, strerror(errno));
            return 1;
        }
    }

    FILE *out;
    int out_is_null = 0;
    if (test_mode) {
        out = fopen("/dev/null", "wb");
        out_is_null = 1;
    } else if (out_path == NULL || strcmp(out_path, "-") == 0 || strcmp(out_path, "stdout") == 0) {
        out = stdout;
    } else if (strcmp(out_path, "null") == 0) {
        out = fopen("/dev/null", "wb");
        out_is_null = 1;
    } else {
        out = fopen(out_path, "wb");
    }
    if (!out) {
        fprintf(stderr, "%s: %s\n", out_path ? out_path : "stdout", strerror(errno));
        if (in != stdin) fclose(in);
        return 1;
    }

    uint64_t bytes_read = 0, bytes_written = 0;
    int rc = LZ4F_decompress_file(in, out, &bytes_read, &bytes_written,
                                  dict, dict_size, opt->use_sparse);
    if (in != stdin) fclose(in);
    if (out != stdout) {
        fflush(out);
        fclose(out);
    } else {
        fflush(out);
    }

    if (rc != 0) {
        if (opt->quiet < 2) {
            fprintf(stderr, "Error 44 : Unrecognized header : file cannot be decoded \n");
        }
        if (out_path && out != stdout && !out_is_null && !test_mode) unlink(out_path);
        return 44;
    }

    if (opt->quiet == 0) {
        const char *disp_in = in_path ? in_path : "stdin";
        fprintf(stderr, "\rDecompressed : %lu MiB  \r%79s\r",
                (unsigned long)(bytes_written >> 20), "");
        print_filename_pad(stderr, disp_in);
        fprintf(stderr, ": decoded %lu bytes \n", (unsigned long)bytes_written);
    }

    if (opt->remove_src && !test_mode && in_path && in != stdin) {
        unlink(in_path);
    }

    return 0;
}

/* Determine default output path for compression */
static char *default_compress_out(const char *in_path) {
    size_t n = strlen(in_path);
    char *out = (char *)malloc(n + 5);
    sprintf(out, "%s.lz4", in_path);
    return out;
}

/* Determine default output path for decompression (strip .lz4) */
static char *default_decompress_out(const char *in_path) {
    size_t n = strlen(in_path);
    if (n >= 4 && strcmp(in_path + n - 4, ".lz4") == 0) {
        char *out = (char *)malloc(n - 3);
        memcpy(out, in_path, n - 4);
        out[n - 4] = '\0';
        return out;
    }
    /* Has no .lz4 ext */
    return NULL;
}

/* List mode */
static int list_file(const char *path, int header_done) {
    if (!header_done) {
        printf("    Frames           Type Block  Compressed  Uncompressed    Ratio   Filename\n");
    }
    struct stat st;
    if (stat(path, &st) != 0 || !S_ISREG(st.st_mode)) {
        fprintf(stderr, "lz4: %s is not a regular file \n", path);
        return 1;
    }
    FILE *f = fopen(path, "rb");
    if (!f) return 1;

    uint8_t magic[4];
    size_t frames = 0;
    const char *type = "LZ4Frame";
    char block[8] = "B4I";
    size_t total_compressed = (size_t)st.st_size;
    uint64_t total_uncompressed = 0;
    int unknown_uncompressed = 0;

    while (1) {
        size_t r = fread(magic, 1, 4, f);
        if (r == 0) break;
        if (r != 4) { fclose(f); return 1; }
        uint32_t m = (uint32_t)magic[0] | ((uint32_t)magic[1]<<8) | ((uint32_t)magic[2]<<16) | ((uint32_t)magic[3]<<24);
        if (m == LZ4F_MAGIC) {
            frames++;
            uint8_t flg, bd;
            if (fread(&flg, 1, 1, f) != 1) { fclose(f); return 1; }
            if (fread(&bd, 1, 1, f) != 1) { fclose(f); return 1; }
            int block_indep = (flg >> 5) & 1;
            int block_checksum = (flg >> 4) & 1;
            int content_size_flag = (flg >> 3) & 1;
            int content_checksum_flag = (flg >> 2) & 1;
            int dict_id_flag = flg & 1;
            int block_size_id = (bd >> 4) & 7;
            sprintf(block, "B%d%c%s", block_size_id, block_indep ? 'I' : 'D', block_checksum ? "X" : "");
            (void)content_checksum_flag;
            if (content_size_flag) {
                uint8_t sz[8];
                if (fread(sz, 1, 8, f) != 8) { fclose(f); return 1; }
                uint64_t cs = 0;
                for (int i = 0; i < 8; i++) cs |= ((uint64_t)sz[i]) << (i*8);
                total_uncompressed += cs;
            } else {
                unknown_uncompressed = 1;
            }
            if (dict_id_flag) {
                uint8_t d[4];
                if (fread(d, 1, 4, f) != 4) { fclose(f); return 1; }
            }
            uint8_t hc;
            if (fread(&hc, 1, 1, f) != 1) { fclose(f); return 1; }
            /* Skip blocks */
            while (1) {
                uint8_t sz_buf[4];
                if (fread(sz_buf, 1, 4, f) != 4) { fclose(f); return 1; }
                uint32_t sz = (uint32_t)sz_buf[0] | ((uint32_t)sz_buf[1]<<8) | ((uint32_t)sz_buf[2]<<16) | ((uint32_t)sz_buf[3]<<24);
                if (sz == 0) break;
                sz &= 0x7fffffffU;
                if (fseek(f, sz, SEEK_CUR) != 0) { fclose(f); return 1; }
                if (block_checksum) {
                    uint8_t bc[4];
                    if (fread(bc, 1, 4, f) != 4) { fclose(f); return 1; }
                }
            }
            if (content_checksum_flag) {
                uint8_t cc[4];
                if (fread(cc, 1, 4, f) != 4) { fclose(f); return 1; }
            }
        } else {
            fclose(f);
            return 1;
        }
    }

    fclose(f);

    /* Derive filename base */
    const char *fname = strrchr(path, '/');
    fname = fname ? fname + 1 : path;

    if (unknown_uncompressed) {
        printf("%10zu       %s   %-3s  %10.2f             -        -   %s\n",
               frames, type, block, (double)total_compressed, fname);
    } else {
        double ratio = total_uncompressed > 0 ? (double)total_compressed / (double)total_uncompressed : 0.0;
        printf("%10zu       %s   %-3s  %10.2f  %12lu  %.4f   %s\n",
               frames, type, block, (double)total_compressed,
               (unsigned long)total_uncompressed, ratio, fname);
    }

    return 0;
}

int main(int argc, char **argv) {
    options_t opt;
    init_options(&opt);

    int mode = MODE_COMPRESS;
    int forced_mode_set = 0;

    /* First scan: determine program name from argv[0] to change defaults */
    const char *bn = strrchr(argv[0], '/');
    bn = bn ? bn + 1 : argv[0];
    if (strstr(bn, "unlz4") != NULL) {
        mode = MODE_DECOMPRESS;
        opt.forced_mode = 1;
        forced_mode_set = 1;
    } else if (strstr(bn, "lz4cat") != NULL) {
        mode = MODE_DECOMPRESS;
        opt.forced_mode = 1;
        forced_mode_set = 1;
        opt.force_stdout = 1;
        opt.multiple = 1;
        opt.force_overwrite = 1;
    }
    (void)forced_mode_set;

    /* Collect positional args */
    const char **positional = (const char **)calloc((size_t)argc + 1, sizeof(char *));
    int npos = 0;
    int force_stdin = 0;
    const char *dict_arg = NULL;

    for (int i = 1; i < argc; i++) {
        const char *arg = argv[i];
        if (arg[0] == '-' && arg[1] != '\0') {
            int r = parse_option(arg, &opt, &mode, &force_stdin);
            if (r == -1) {
                fprintf(stderr, "Incorrect parameters\n");
                print_usage_short(stderr);
                free(positional);
                return 1;
            }
            if (r == 1) {
                /* It was a bare "-" meaning stdin */
                positional[npos++] = "-";
            }
            if (r == 2) {
                /* Need next arg for dict file */
                if (i + 1 >= argc) {
                    fprintf(stderr, "Incorrect parameters\n");
                    print_usage_short(stderr);
                    free(positional);
                    return 1;
                }
                dict_arg = argv[++i];
            }
        } else {
            positional[npos++] = arg;
        }
    }

    if (dict_arg && !opt.dict_file) opt.dict_file = dict_arg;

    /* If a --list mode was set, list the files */
    if (mode == MODE_LIST) {
        int rc = 0;
        if (npos == 0) {
            fprintf(stderr, "lz4: --list requires at least one filename \n");
            free(positional);
            return 1;
        }
        /* Print header */
        printf("    Frames           Type Block  Compressed  Uncompressed    Ratio   Filename\n");
        for (int i = 0; i < npos; i++) {
            if (list_file(positional[i], 1) != 0) rc = 1;
        }
        free(positional);
        return rc;
    }

    /* Dict file load */
    uint8_t *dict_data = NULL;
    size_t dict_size = 0;
    if (opt.dict_file) {
        dict_data = load_dict(opt.dict_file, &dict_size);
        if (!dict_data) {
            fprintf(stderr, "%s: %s \n", opt.dict_file, strerror(errno));
            free(positional);
            return 1;
        }
    }

    /* Benchmark mode - minimal stub */
    if (mode == MODE_BENCHMARK) {
        /* Stub: just exit 0 since we can't easily implement this from scratch */
        free(positional);
        free(dict_data);
        return 0;
    }

    /* Auto-detect mode from input name if not forced */
    if (!opt.forced_mode) {
        if (npos >= 1 && has_lz4_ext(positional[0])) {
            mode = MODE_DECOMPRESS;
        }
    }

    /* Determine input/output */
    const char *input = NULL;
    const char *output = NULL;

    if (opt.multiple || mode == MODE_TEST) {
        /* Process each file individually */
        int rc = 0;
        if (npos == 0) {
            /* Use stdin */
            positional[0] = "-";
            npos = 1;
        }
        for (int i = 0; i < npos; i++) {
            const char *in = positional[i];
            if (mode == MODE_TEST) {
                if (decompress_one(in, NULL, &opt, dict_data, dict_size, 1) != 0) rc = 1;
            } else if (mode == MODE_DECOMPRESS) {
                char *out = NULL;
                if (opt.force_stdout) {
                    out = NULL;
                } else {
                    out = default_decompress_out(in);
                    if (!out) {
                        fprintf(stderr, "%s: unknown suffix -- ignored \n", in);
                        rc = 1;
                        continue;
                    }
                    if (file_exists(out) && !opt.force_overwrite) {
                        fprintf(stderr, "%s already exists; not overwritten  \n", out);
                        rc = 2;
                        free(out);
                        continue;
                    }
                }
                int r = decompress_one(in, opt.force_stdout ? NULL : out, &opt, dict_data, dict_size, 0);
                if (r != 0) rc = r;
                free(out);
            } else {
                /* MODE_COMPRESS */
                char *out = NULL;
                if (opt.force_stdout) {
                    out = NULL;
                } else {
                    out = default_compress_out(in);
                    if (file_exists(out) && !opt.force_overwrite) {
                        fprintf(stderr, "%s already exists; not overwritten  \n", out);
                        rc = 2;
                        free(out);
                        continue;
                    }
                }
                int r = compress_one(in, opt.force_stdout ? NULL : out, &opt, dict_data, dict_size);
                if (r != 0) rc = r;
                free(out);
            }
        }
        free(positional);
        free(dict_data);
        return rc;
    }

    /* Single input/output mode */
    if (npos == 0) {
        input = NULL;  /* stdin */
    } else if (npos == 1) {
        input = positional[0];
    } else if (npos == 2) {
        input = positional[0];
        output = positional[1];
    } else {
        fprintf(stderr, "Error : %s won't be used ! Do you want multiple input files (-m) ? \n",
                positional[2]);
        free(positional);
        free(dict_data);
        return 1;
    }

    /* Determine output */
    char *default_out = NULL;
    if (!output) {
        if (opt.force_stdout) {
            output = NULL;  /* stdout */
        } else if (!isatty(fileno(stdout))) {
            /* stdout is a pipe/file - use stdout */
            output = NULL;
        } else {
            /* stdout is console */
            if (input == NULL) {
                fprintf(stderr, "Cannot determine an output filename \n");
                fprintf(stderr, "Incorrect parameters\n");
                print_usage_short(stderr);
                free(positional);
                free(dict_data);
                return 1;
            }
            if (mode == MODE_COMPRESS) {
                default_out = default_compress_out(input);
                output = default_out;
                if (opt.quiet == 0) {
                    fprintf(stderr, "Compressed filename will be : %s \n", output);
                }
            } else if (mode == MODE_DECOMPRESS) {
                default_out = default_decompress_out(input);
                if (!default_out) {
                    fprintf(stderr, "Cannot determine an output filename \n");
                    fprintf(stderr, "Incorrect parameters\n");
                    print_usage_short(stderr);
                    free(positional);
                    free(dict_data);
                    return 1;
                }
                output = default_out;
                if (opt.quiet == 0) {
                    fprintf(stderr, "Decoding file %s \n", output);
                }
            }
        }
    }

    /* Check overwrite */
    if (output && file_exists(output) && !opt.force_overwrite) {
        /* Check if writing to a device file (/dev/null, stdout, etc.) */
        struct stat st;
        if (stat(output, &st) == 0 && S_ISREG(st.st_mode)) {
            if (isatty(fileno(stdin))) {
                fprintf(stderr, "%s already exists; not overwritten  \n", output);
                free(positional);
                free(default_out);
                free(dict_data);
                return 2;
            } else {
                if (!ask_overwrite(output)) {
                    fprintf(stderr, "    not overwritten  \n");
                    free(positional);
                    free(default_out);
                    free(dict_data);
                    return 2;
                }
            }
        }
    }

    int rc;
    if (mode == MODE_DECOMPRESS) {
        rc = decompress_one(input, output, &opt, dict_data, dict_size, 0);
    } else if (mode == MODE_TEST) {
        rc = decompress_one(input, NULL, &opt, dict_data, dict_size, 1);
    } else {
        rc = compress_one(input, output, &opt, dict_data, dict_size);
    }

    free(positional);
    free(default_out);
    free(dict_data);
    return rc;
}
