    uint8_t *input_buf = (uint8_t *)malloc(block_size);
    if (!input_buf) return -1;

    /* Read first block */
    size_t first_n = fread(input_buf, 1, block_size, in);

    /* Determine effective block size ID: if first_n < block_size (i.e., single block),
     * use the smallest fitting size. */
    int effective_id = block_size_id;
    if (first_n < block_size) {
        int min_id = block_size_id_for(first_n);
        if (min_id < effective_id) effective_id = min_id;
    } else if (content_size > 0 && content_size < (1ULL << 31)) {
        int min_id = block_size_id_for((size_t)content_size);
        if (min_id < effective_id) effective_id = min_id;
