    write_le32(header + hpos, LZ4F_MAGIC); hpos += 4;
    uint8_t flg = 0x40;
    if (prefs->block_mode == 1) flg |= 0x20;
    if (prefs->block_checksum) flg |= 0x10;
    if (prefs->content_size) flg |= 0x08;
    if (prefs->content_checksum) flg |= 0x04;
    header[hpos++] = flg;
    uint8_t bd = (uint8_t)(effective_id << 4);
    header[hpos++] = bd;
    if (prefs->content_size) {
        write_le64(header + hpos, content_size);
        hpos += 8;
