            int cs = LZ4_compress_default((const char *)(cur_buf + off), (char *)output_buf, (int)chunk, compressed_bound);
            uint8_t sz_buf[4];
            const uint8_t *block_data;
            size_t block_len;
            if (cs > 0 && (size_t)cs < chunk) {
                write_le32(sz_buf, (uint32_t)cs);
