    (void)dict; (void)dict_size;
    int block_size_id = prefs->block_size_id;
    if (block_size_id < 4) block_size_id = 4;
    if (block_size_id > 7) block_size_id = 7;

    /* Allocate buffer of configured block size */
    size_t block_size = LZ4F_block_size(block_size_id);
    uint8_t *input_buf = (uint8_t *)malloc(block_size);
    if (!input_buf) return -1;

    /* Read first block */
    size_t first_n = fread(input_buf, 1, block_size, in);

    /* Determine effective block size ID: if first_n < block_size (i.e., single block),
     * use the smallest fitting size. */
    int effective_id = block_size_id;
    if (first_n < block_size) {
        int min_id = block_size_id_for(first_n);
        if (min_id < effective_id) effective_id = min_id;
    } else if (content_size > 0 && content_size < (1ULL << 31)) {
        int min_id = block_size_id_for((size_t)content_size);
        if (min_id < effective_id) effective_id = min_id;
    }

    size_t effective_block_size = LZ4F_block_size(effective_id);

    /* Write header */
    uint8_t header[19];
    size_t hpos = 0;
    write_le32(header + hpos, LZ4F_MAGIC); hpos += 4;
    uint8_t flg = 0x40;
    if (prefs->block_mode == 1) flg |= 0x20;
    if (prefs->block_checksum) flg |= 0x10;
    if (prefs->content_size) flg |= 0x08;
    if (prefs->content_checksum) flg |= 0x04;
    header[hpos++] = flg;
    uint8_t bd = (uint8_t)(effective_id << 4);
    header[hpos++] = bd;
    if (prefs->content_size) {
        write_le64(header + hpos, content_size);
        hpos += 8;
    }
    uint32_t hc = XXH32(header + 4, hpos - 4, 0);
    header[hpos++] = (uint8_t)((hc >> 8) & 0xff);

    if (fwrite(header, 1, hpos, out) != hpos) { free(input_buf); return -1; }
    *bytes_written += hpos;

    int compressed_bound = LZ4_compressBound((int)effective_block_size);
    uint8_t *output_buf = (uint8_t *)malloc((size_t)compressed_bound);
    if (!output_buf) { free(input_buf); return -1; }

    XXH32_state_t content_hash;
    XXH32_reset(&content_hash, 0);

    /* Process first block */
    size_t n = first_n;
    uint8_t *cur_buf = input_buf;

    while (1) {
        if (n == 0) break;
        *bytes_read += n;
        if (prefs->content_checksum) XXH32_update(&content_hash, cur_buf, n);

        /* If n > effective_block_size (shouldn't happen now), chunk it */
        size_t off = 0;
        while (off < n) {
            size_t chunk = n - off;
            if (chunk > effective_block_size) chunk = effective_block_size;
            int cs = LZ4_compress_default((const char *)(cur_buf + off), (char *)output_buf, (int)chunk, compressed_bound);
            uint8_t sz_buf[4];
            const uint8_t *block_data;
            size_t block_len;
            if (cs > 0 && (size_t)cs < chunk) {
                write_le32(sz_buf, (uint32_t)cs);
                block_data = output_buf;
                block_len = (size_t)cs;
            } else {
                write_le32(sz_buf, (uint32_t)chunk | 0x80000000U);
                block_data = cur_buf + off;
                block_len = chunk;
            }
            if (fwrite(sz_buf, 1, 4, out) != 4) { free(input_buf); free(output_buf); return -1; }
            *bytes_written += 4;
            if (fwrite(block_data, 1, block_len, out) != block_len) { free(input_buf); free(output_buf); return -1; }
            *bytes_written += block_len;
            if (prefs->block_checksum) {
                uint32_t bcs = XXH32(block_data, block_len, 0);
                uint8_t bc_buf[4];
                write_le32(bc_buf, bcs);
                if (fwrite(bc_buf, 1, 4, out) != 4) { free(input_buf); free(output_buf); return -1; }
                *bytes_written += 4;
            }
            off += chunk;
        }

        if (n < block_size) break;
        n = fread(input_buf, 1, block_size, in);
    }

    /* EndMark */
    uint8_t endmark[4] = {0,0,0,0};
    if (fwrite(endmark, 1, 4, out) != 4) { free(input_buf); free(output_buf); return -1; }
    *bytes_written += 4;

    if (prefs->content_checksum) {
        uint32_t cc = XXH32_digest(&content_hash);
        uint8_t cc_buf[4];
        write_le32(cc_buf, cc);
        if (fwrite(cc_buf, 1, 4, out) != 4) { free(input_buf); free(output_buf); return -1; }
        *bytes_written += 4;
    }

    free(input_buf);
    free(output_buf);
    return 0;
}
